def encode(message):
    encoded_message = ""
    vowels = "aeiou"

    for char in message:
        if char.isalpha():
            # Swap case of the letter
            if char.lower() == char.upper():
                encoded_message += char.swapcase()
            else:
                # Replace vowel with 2 places ahead alphabet
                if char in vowels:
                    index = (ord(char) - ord('a') + 1) % 26
                    encoded_message += chr(ord('a') + index)
                else:
                    encoded_message += char
        else:
            # Append non-alphabetic characters as is
            encoded_message += char

    return encoded_message
```

