def bf(planet1, planet2):
    """
    This function takes two planet names as strings and returns a tuple containing all planets whose orbits are located between the orbit of planet1 and the orbit of planet2,
    sorted by their proximity to the Sun.

    The function checks if both planet1 and planet2 are valid planet names. If not, it returns an empty tuple.
    """
    # Validate input
    if not isinstance(planet1, str) or not isinstance(planet2, str):
        return ()

    # Define a list of planets in our solar system
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]

    # Find the index of planet1 and planet2 in the list
    idx1, idx2 = -1, -1

    for i, planet in enumerate(planets):
        if planet == planet1:
            idx1 = i
        elif planet == planet2:
            idx2 = i

    # If either planet is not found, return an empty tuple
    if idx1 == -1 or idx2 == -1:
        return ()

    # Sort the planets by their proximity to the Sun
    sorted_planets = sorted(planets[idx1:idx2 + 1])

    # Return a tuple containing only the sorted planets
    return tuple(sorted_planets)
