def calculate_sum(n):
    """
    Calculate the sum of a sequence starting from 0 up to n/2 with a step of -2.

    Args:
    n (int): The upper limit for the sequence calculation.

    Returns:
    int: The calculated sum.
    """
    if n % 2 == 1:
        return calculate_sum(n + 1)
    else:
        return n * (n // 2) + calculate_sum(n - 2)

# Example usage
