def get_odd_collatz(n):
    if n == 1:
        return [1]

    # Initialize an empty list to store odd numbers in the Collatz sequence
    odd_numbers = []

    while n != 1:
        if n % 2 == 0:
            n //= 2
        else:
            n = 3 * n + 1
        odd_numbers.append(n)

    # Add the last odd number to the list, as it is not part of the Collatz sequence
    odd_numbers.append(n)

    return sorted(odd_numbers)
